fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let track: i32 = w * 8;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 5 {
            host::display::state_set(8 + i * 2, i * (track / 5));
            host::display::state_set(9 + i * 2, 16);
            i = i + 1;
        }
    }
    let mut x = [0; 5];
    let mut v = [0; 5];
    let mut i: i32 = 0;
    while i < 5 {
        x[i] = host::display::state_get(8 + i * 2);
        v[i] = host::display::state_get(9 + i * 2);
        i = i + 1;
    }
    let brake: bool = host::display::pointer_down() == 1;
    i = 0;
    while i < 5 {
        let a: i32 = (i + 1) % 5;
        let mut gap: i32 = x[a] - x[i];
        if gap < 0 { gap = gap + track; }
        gap = gap - 224;
        if i == 0 && brake {
            v[i] = 0;
        } else if gap < 400 {
            v[i] = v[i] - 4;
        } else if v[i] < 20 {
            v[i] = v[i] + 1;
        }
        if v[i] < 0 { v[i] = 0; }
        if gap < 40 { v[i] = 0; }
        i = i + 1;
    }
    i = 0;
    while i < 5 {
        x[i] = x[i] + v[i];
        if x[i] >= track { x[i] = x[i] - track; }
        host::display::state_set(8 + i * 2, x[i]);
        host::display::state_set(9 + i * 2, v[i]);
        i = i + 1;
    }
    host::display::clear(0x101010);
    let ry: i32 = h / 2;
    host::display::fill_rect(0, ry - 20, w, 40, 0x282828);
    i = 0;
    while i < 5 {
        let c: i32 = if v[i] >= 16 { 0x40cc50 } else if v[i] >= 8 { 0xddbb30 } else { 0xdd4030 };
        host::display::fill_rect(x[i] / 8, ry - 6, 24, 12, c);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "HOLD = BRAKE CAR 0", 0x808080, 1);
    host::display::present();
}
